stages.source:
vec2 uv = fragCoord / iResolution.xy;
float pixelAspect = iResolution.z;
fragColor = vec4(uv.x, uv.y, pixelAspect - 1.0, 1.0);

vec2 uv = fragCoord / iResolution.xy;
float diagonal = (uv.x + uv.y) * 0.5;
fragColor = vec4(diagonal, diagonal, 0.4, 1.0);

vec2 uv = fragCoord / iResolution.xy;
vec2 p = uv * 2.0 - 1.0;
fragColor = vec4(p.x, p.y, 0.5, 1.0);

vec2 uv = fragCoord / iResolution.xy;
vec2 p = uv * 2.0 - 1.0;
float distanceFromCentre = length(p);
fragColor = vec4(distanceFromCentre, distanceFromCentre, distanceFromCentre, 1.0);

vec2 uv = fragCoord / iResolution.xy;
vec2 p = uv * 2.0 - 1.0;
p.x *= iResolution.x / iResolution.y;
float distanceFromCentre = length(p);
fragColor = vec4(distanceFromCentre, distanceFromCentre, distanceFromCentre, 1.0);

vec2 uv = fragCoord / iResolution.xy;
vec2 p = uv * 2.0 - 1.0;
p.x *= iResolution.x / iResolution.y;
fragColor = vec4(p.x, p.y, 0.5, 1.0);

vec2 uv = fragCoord / iResolution.xy;
float brightness = sin(iTime * 2.0) * 0.5 + 0.5;
fragColor = vec4(uv.x, uv.y, brightness, 1.0);

vec2 uv = fragCoord / iResolution.xy;
vec2 p = uv * 2.0 - 1.0;
p.x *= iResolution.x / iResolution.y;
fragColor = vec4(p.x * 0.5 + 0.5, p.y * 0.5 + 0.5, 0.5, 1.0);

vec2 uv = fragCoord / iResolution.xy;
float brightness = uv.x;
fragColor = vec4(brightness, brightness, brightness, 1.0);

vec2 uv = fragCoord / iResolution.xy;
float lit = step(0.5, uv.x);
fragColor = vec4(lit, lit, lit, 1.0);

vec2 uv = fragCoord / iResolution.xy;
float edge = 0.5 + sin(iTime) * 0.35;
float lit = step(edge, uv.x);
fragColor = vec4(lit, lit, lit, 1.0);

vec2 uv = fragCoord / iResolution.xy;
float diagonal = (uv.x + uv.y) * 0.5;
float lit = step(0.5, diagonal);
fragColor = vec4(lit, lit, lit, 1.0);

vec2 uv = fragCoord / iResolution.xy;
float diagonal = (uv.x + uv.y) * 0.5;
float lit = step(0.5, diagonal);
fragColor = vec4(lit, lit, lit, 1.0);

vec2 uv = fragCoord / iResolution.xy;
float diagonal = (uv.x + uv.y) * 0.5;
float lit = smoothstep(0.48, 0.52, diagonal);
fragColor = vec4(lit, lit, lit, 1.0);

vec2 uv = fragCoord / iResolution.xy;
float diagonal = (uv.x + uv.y) * 0.5;
float lit = smoothstep(0.3, 0.7, diagonal);
fragColor = vec4(lit, lit, lit, 1.0);

vec2 uv = fragCoord / iResolution.xy;
float diagonal = (uv.x + uv.y) * 0.5;
float halfWidth = 0.02 + (sin(iTime) * 0.5 + 0.5) * 0.28;
float lit = smoothstep(0.5 - halfWidth, 0.5 + halfWidth, diagonal);
fragColor = vec4(lit, lit, lit, 1.0);

vec3 cool = vec3(0.31, 0.84, 1.0);
vec3 warm = vec3(1.0, 0.42, 0.42);
vec3 colour = mix(cool, warm, 0.5);
fragColor = vec4(colour, 1.0);

vec2 uv = fragCoord / iResolution.xy;
vec3 cool = vec3(0.31, 0.84, 1.0);
vec3 warm = vec3(1.0, 0.42, 0.42);
vec3 colour = mix(cool, warm, uv.x);
fragColor = vec4(colour, 1.0);

vec2 uv = fragCoord / iResolution.xy;
vec3 cool = vec3(0.31, 0.84, 1.0);
vec3 warm = vec3(1.0, 0.42, 0.42);
float factor = smoothstep(0.35, 0.65, uv.x);
vec3 colour = mix(cool, warm, factor);
fragColor = vec4(colour, 1.0);

vec2 uv = fragCoord / iResolution.xy;
vec3 red = vec3(1.0, 0.0, 0.0);
vec3 green = vec3(0.0, 1.0, 0.0);
vec3 colour = mix(red, green, uv.x);
fragColor = vec4(colour, 1.0);

vec2 uv = fragCoord / iResolution.xy;
float boosted = uv.x * 2.5;
fragColor = vec4(boosted, boosted, boosted, 1.0);

vec2 uv = fragCoord / iResolution.xy;
float boosted = clamp(uv.x * 2.5, 0.0, 1.0);
fragColor = vec4(boosted, boosted, boosted, 1.0);

vec2 uv = fragCoord / iResolution.xy;
vec3 cool = vec3(0.31, 0.84, 1.0);
vec3 warm = vec3(1.0, 0.42, 0.42);
float factor = uv.x * 2.5 - 0.6;
vec3 colour = mix(cool, warm, factor);
fragColor = vec4(colour, 1.0);

vec2 uv = fragCoord / iResolution.xy;
vec3 cool = vec3(0.31, 0.84, 1.0);
vec3 warm = vec3(1.0, 0.42, 0.42);
float factor = clamp(uv.x * 2.5 - 0.6, 0.0, 1.0);
vec3 colour = mix(cool, warm, factor);
fragColor = vec4(colour, 1.0);

vec2 uv = fragCoord / iResolution.xy;
float narrow = uv.x * 0.4 + 0.3;
fragColor = vec4(narrow, narrow, narrow, 1.0);

vec2 uv = fragCoord / iResolution.xy;
float inMin = 0.25;
float inMax = 0.75;
float t = (uv.x - inMin) / (inMax - inMin);
fragColor = vec4(t, t, t, 1.0);

vec2 uv = fragCoord / iResolution.xy;
float eased = pow(uv.x, 3.0);
fragColor = vec4(eased, eased, eased, 1.0);

vec2 uv = fragCoord / iResolution.xy;
float rise = pow(uv.x, 3.0);
float decay = exp(-uv.x * 4.0);
float upper = step(0.5, uv.y);
float eased = mix(rise, decay, upper);
fragColor = vec4(eased, eased, eased, 1.0);

vec2 uv = fragCoord / iResolution.xy;
vec2 p = uv * 2.0 - 1.0;
p.x *= iResolution.x / iResolution.y;

float d = length(p);

fragColor = vec4(vec3(d), 1.0);

vec2 uv = fragCoord / iResolution.xy;
vec2 p = uv * 2.0 - 1.0;
p.x *= iResolution.x / iResolution.y;

float d = length(p) - 0.5;

fragColor = vec4(vec3(d), 1.0);

vec2 uv = fragCoord / iResolution.xy;
vec2 p = uv * 2.0 - 1.0;
p.x *= iResolution.x / iResolution.y;

float d = length(p) - 0.5;

vec3 inside = vec3(0.31, 0.84, 1.0);
vec3 outside = vec3(1.0, 0.45, 0.42);
vec3 colour = mix(inside, outside, step(0.0, d));

fragColor = vec4(colour, 1.0);

vec2 uv = fragCoord / iResolution.xy;
vec2 p = uv * 2.0 - 1.0;
p.x *= iResolution.x / iResolution.y;

float d = length(p) - 0.5;

float ring = smoothstep(-0.04, -0.02, d) - smoothstep(0.02, 0.04, d);

vec3 colour = mix(vec3(0.05, 0.05, 0.08), vec3(0.78, 0.96, 0.39), ring);

fragColor = vec4(colour, 1.0);

vec2 uv = fragCoord / iResolution.xy;
vec2 p = uv * 2.0 - 1.0;
p.x *= iResolution.x / iResolution.y;

float radius = 0.3;
float d = length(p) - radius;

float fill = 1.0 - smoothstep(0.0, 0.012, d);

vec3 colour = mix(vec3(0.05, 0.05, 0.08), vec3(0.31, 0.84, 1.0), fill);

fragColor = vec4(colour, 1.0);

vec2 uv = fragCoord / iResolution.xy;
vec2 p = uv * 2.0 - 1.0;
p.x *= iResolution.x / iResolution.y;

vec2 centre = vec2(0.2, -0.2);
float radius = 0.3;
float d = length(p - centre) - radius;

float fill = 1.0 - smoothstep(0.0, 0.012, d);

vec3 colour = mix(vec3(0.05, 0.05, 0.08), vec3(0.31, 0.84, 1.0), fill);

fragColor = vec4(colour, 1.0);

vec2 uv = fragCoord / iResolution.xy;
vec2 p = uv * 2.0 - 1.0;
p.x *= iResolution.x / iResolution.y;

vec2 centre = vec2(sin(iTime) * 0.24, cos(iTime) * 0.45);
float radius = 0.22 + sin(iTime * 2.0) * 0.06;
float d = length(p - centre) - radius;

float fill = 1.0 - smoothstep(0.0, 0.012, d);

vec3 colour = mix(vec3(0.05, 0.05, 0.08), vec3(0.31, 0.84, 1.0), fill);

fragColor = vec4(colour, 1.0);

vec2 uv = fragCoord / iResolution.xy;
vec2 p = uv * 2.0 - 1.0;
p.x *= iResolution.x / iResolution.y;

float d = length(p) - 0.26;

float fill = 1.0 - smoothstep(0.0, 0.012, d);
float glow = 1.0 - smoothstep(0.0, 0.5, d);

vec3 colour = vec3(0.05, 0.05, 0.08);
colour = mix(colour, vec3(0.18, 0.42, 0.55), glow);
colour = mix(colour, vec3(0.31, 0.84, 1.0), fill);

fragColor = vec4(colour, 1.0);

vec2 uv = fragCoord / iResolution.xy;
vec2 p = uv * 2.0 - 1.0;
p.x *= iResolution.x / iResolution.y;

vec2 q = abs(p);

fragColor = vec4(q.x, q.y, 0.25, 1.0);

vec2 uv = fragCoord / iResolution.xy;
vec2 p = uv * 2.0 - 1.0;
p.x *= iResolution.x / iResolution.y;

vec2 halfSize = vec2(0.34, 0.22);
vec2 q = abs(p) - halfSize;

float d = max(q.x, q.y);

float fill = 1.0 - smoothstep(0.0, 0.012, d);

vec3 colour = mix(vec3(0.05, 0.05, 0.08), vec3(0.78, 0.96, 0.39), fill);

fragColor = vec4(colour, 1.0);

vec2 uv = fragCoord / iResolution.xy;
vec2 p = uv * 2.0 - 1.0;
p.x *= iResolution.x / iResolution.y;

vec2 q = abs(p) - vec2(0.34, 0.22);

float outside = length(max(q, 0.0));

float glow = 1.0 - smoothstep(0.0, 0.35, outside);

vec3 colour = mix(vec3(0.05, 0.05, 0.08), vec3(0.78, 0.96, 0.39), glow);

fragColor = vec4(colour, 1.0);

vec2 uv = fragCoord / iResolution.xy;
vec2 p = uv * 2.0 - 1.0;
p.x *= iResolution.x / iResolution.y;

float rounding = 0.1;
vec2 q = abs(p) - (vec2(0.34, 0.22) - rounding);

float d = length(max(q, 0.0)) - rounding;

float fill = 1.0 - smoothstep(0.0, 0.012, d);

vec3 colour = mix(vec3(0.05, 0.05, 0.08), vec3(0.78, 0.96, 0.39), fill);

fragColor = vec4(colour, 1.0);

vec2 uv = fragCoord / iResolution.xy;
vec2 p = uv * 2.0 - 1.0;
p.x *= iResolution.x / iResolution.y;

float a = length(p - vec2(-0.16, 0.0)) - 0.26;
float b = length(p - vec2(0.16, 0.0)) - 0.26;

float fillA = 1.0 - smoothstep(0.0, 0.012, a);
float fillB = 1.0 - smoothstep(0.0, 0.012, b);

vec3 colour = vec3(0.05, 0.05, 0.08);
colour = mix(colour, vec3(0.31, 0.84, 1.0), fillA);
colour = mix(colour, vec3(1.0, 0.45, 0.42), fillB);

fragColor = vec4(colour, 1.0);

vec2 uv = fragCoord / iResolution.xy;
vec2 p = uv * 2.0 - 1.0;
p.x *= iResolution.x / iResolution.y;

float a = length(p - vec2(-0.16, 0.0)) - 0.26;
float b = length(p - vec2(0.16, 0.0)) - 0.26;

float d = min(a, b);

float fill = 1.0 - smoothstep(0.0, 0.012, d);

vec3 colour = mix(vec3(0.05, 0.05, 0.08), vec3(0.78, 0.96, 0.39), fill);

fragColor = vec4(colour, 1.0);

vec2 uv = fragCoord / iResolution.xy;
vec2 p = uv * 2.0 - 1.0;
p.x *= iResolution.x / iResolution.y;

float a = length(p - vec2(-0.16, 0.0)) - 0.26;
float b = length(p - vec2(0.16, 0.0)) - 0.26;

float d = max(a, b);

float fill = 1.0 - smoothstep(0.0, 0.012, d);

vec3 colour = mix(vec3(0.05, 0.05, 0.08), vec3(0.78, 0.96, 0.39), fill);

fragColor = vec4(colour, 1.0);

vec2 uv = fragCoord / iResolution.xy;
vec2 p = uv * 2.0 - 1.0;
p.x *= iResolution.x / iResolution.y;

float a = length(p - vec2(-0.16, 0.0)) - 0.26;
float b = length(p - vec2(0.16, 0.0)) - 0.26;

float d = max(a, -b);

float fill = 1.0 - smoothstep(0.0, 0.012, d);

vec3 colour = mix(vec3(0.05, 0.05, 0.08), vec3(0.78, 0.96, 0.39), fill);

fragColor = vec4(colour, 1.0);

vec2 uv = fragCoord / iResolution.xy;
vec2 p = uv * 2.0 - 1.0;
p.x *= iResolution.x / iResolution.y;

float d = length(p) - 0.34;

float fill = 1.0 - smoothstep(0.0, 0.012, d);

vec3 colour = mix(vec3(0.05, 0.05, 0.08), vec3(0.78, 0.96, 0.39), fill);

fragColor = vec4(colour, 1.0);

vec2 uv = fragCoord / iResolution.xy;
float zoom = 1.85 + sin(iTime * 0.6) * 1.15;
vec2 p = (uv * 2.0 - 1.0) * zoom;
p.x *= iResolution.x / iResolution.y;

float d = length(p) - 0.34;

float fill = 1.0 - smoothstep(0.0, 0.012, d);

vec3 colour = mix(vec3(0.05, 0.05, 0.08), vec3(0.78, 0.96, 0.39), fill);

fragColor = vec4(colour, 1.0);

vec2 uv = fragCoord / iResolution.xy;
float zoom = 1.85 + sin(iTime * 0.6) * 1.15;
vec2 p = (uv * 2.0 - 1.0) * zoom;
p.x *= iResolution.x / iResolution.y;

float d = length(p) - 0.34;

float w = fwidth(d);
float fill = 1.0 - smoothstep(-w, w, d);

vec3 colour = mix(vec3(0.05, 0.05, 0.08), vec3(0.78, 0.96, 0.39), fill);

fragColor = vec4(colour, 1.0);

vec2 uv = fragCoord / iResolution.xy;
float zoom = 1.85 + sin(iTime * 0.6) * 1.15;
vec2 p = (uv * 2.0 - 1.0) * zoom;
p.x *= iResolution.x / iResolution.y;

float rounding = 0.08;
vec2 q = abs(p) - (vec2(0.3, 0.2) - rounding);
float box = length(max(q, 0.0)) - rounding;

float ball = length(p - vec2(0.0, 0.3)) - 0.14;

float d = min(box, ball);

float w = fwidth(d);
float fill = 1.0 - smoothstep(-w, w, d);

vec3 colour = mix(vec3(0.05, 0.05, 0.08), vec3(0.78, 0.96, 0.39), fill);

fragColor = vec4(colour, 1.0);

vec2 uv = fragCoord / iResolution.xy;

vec3 colour = vec3(uv.x, uv.y, 0.25);

fragColor = vec4(colour, 1.0);

vec2 uv = fragCoord / iResolution.xy;

float ramp = uv.x * 2.0 - 0.5;

fragColor = vec4(vec3(ramp), 1.0);

vec2 uv = fragCoord / iResolution.xy;

float evenInAppearance = uv.x;
float evenInLight = pow(uv.x, 2.2);

float value = mix(evenInAppearance, evenInLight, step(0.5, uv.y));

fragColor = vec4(vec3(value), 1.0);

vec2 uv = fragCoord / iResolution.xy;

vec3 cool = vec3(0.13, 0.29, 0.62);
vec3 warm = vec3(0.98, 0.62, 0.24);

vec3 colour = mix(cool, warm, uv.x);

fragColor = vec4(colour, 1.0);

vec2 uv = fragCoord / iResolution.xy;
vec2 p = uv * 2.0 - 1.0;
p.x *= iResolution.x / iResolution.y;

float d = length(p) - 0.4;
float t = clamp(d + 0.5, 0.0, 1.0);

vec3 inner = vec3(0.95, 0.35, 0.42);
vec3 outer = vec3(0.1, 0.14, 0.3);

vec3 colour = mix(inner, outer, t);

fragColor = vec4(colour, 1.0);

vec2 uv = fragCoord / iResolution.xy;

vec3 low = vec3(0.05, 0.13, 0.35);
vec3 mid = vec3(0.85, 0.28, 0.35);
vec3 high = vec3(0.99, 0.86, 0.52);

vec3 colour = mix(low, mid, smoothstep(0.0, 0.5, uv.x));
colour = mix(colour, high, smoothstep(0.5, 1.0, uv.x));

fragColor = vec4(colour, 1.0);

vec2 uv = fragCoord / iResolution.xy;
vec2 p = uv * 2.0 - 1.0;
p.x *= iResolution.x / iResolution.y;

float radius = 0.42;
float d = length(p) - radius;

float w = fwidth(d);
float fill = 1.0 - smoothstep(-w, w, d);

float inward = clamp(-d / radius, 0.0, 1.0);
vec3 shape = mix(vec3(0.86, 0.22, 0.3), vec3(0.99, 0.9, 0.55), inward);

vec3 colour = mix(vec3(0.05, 0.05, 0.08), shape, fill);

fragColor = vec4(colour, 1.0);

vec2 uv = fragCoord / iResolution.xy;
vec2 p = uv * 2.0 - 1.0;
p.x *= iResolution.x / iResolution.y;

float r = length(p - vec2(-0.22, 0.13)) - 0.26;
float g = length(p - vec2(0.22, 0.13)) - 0.26;
float b = length(p - vec2(0.0, -0.24)) - 0.26;

vec3 colour;
colour.r = 1.0 - smoothstep(-fwidth(r), fwidth(r), r);
colour.g = 1.0 - smoothstep(-fwidth(g), fwidth(g), g);
colour.b = 1.0 - smoothstep(-fwidth(b), fwidth(b), b);

fragColor = vec4(colour, 1.0);

vec2 uv = fragCoord / iResolution.xy;
vec2 p = uv * 2.0 - 1.0;
p.x *= iResolution.x / iResolution.y;

float r = length(p - vec2(-0.22, 0.13)) - 0.26;
float g = length(p - vec2(0.22, 0.13)) - 0.26;
float b = length(p - vec2(0.0, -0.24)) - 0.26;

vec3 colour;
colour.r = 1.0 - smoothstep(-fwidth(r), fwidth(r), r);
colour.g = 1.0 - smoothstep(-fwidth(g), fwidth(g), g);
colour.b = 1.0 - smoothstep(-fwidth(b), fwidth(b), b);

float brightness = (colour.r + colour.g + colour.b) / 3.0;

fragColor = vec4(vec3(brightness), 1.0);

vec2 uv = fragCoord / iResolution.xy;
vec2 p = uv * 2.0 - 1.0;
p.x *= iResolution.x / iResolution.y;

float r = length(p - vec2(-0.22, 0.13)) - 0.26;
float g = length(p - vec2(0.22, 0.13)) - 0.26;
float b = length(p - vec2(0.0, -0.24)) - 0.26;

vec3 colour;
colour.r = 1.0 - smoothstep(-fwidth(r), fwidth(r), r);
colour.g = 1.0 - smoothstep(-fwidth(g), fwidth(g), g);
colour.b = 1.0 - smoothstep(-fwidth(b), fwidth(b), b);

float luma = dot(colour, vec3(0.2126, 0.7152, 0.0722));

fragColor = vec4(vec3(luma), 1.0);

vec2 uv = fragCoord / iResolution.xy;
vec2 p = uv * 2.0 - 1.0;
p.x *= iResolution.x / iResolution.y;

float r = length(p - vec2(-0.22, 0.13)) - 0.26;
float g = length(p - vec2(0.22, 0.13)) - 0.26;
float b = length(p - vec2(0.0, -0.24)) - 0.26;

vec3 colour;
colour.r = 1.0 - smoothstep(-fwidth(r), fwidth(r), r);
colour.g = 1.0 - smoothstep(-fwidth(g), fwidth(g), g);
colour.b = 1.0 - smoothstep(-fwidth(b), fwidth(b), b);

float amount = 1.6 + sin(iTime) * 1.4;
vec3 contrasted = clamp((colour - 0.5) * amount + 0.5, 0.0, 1.0);

fragColor = vec4(contrasted, 1.0);

vec2 uv = fragCoord / iResolution.xy;

float v = 0.5 + 0.5 * cos(6.28318 * uv.x);

fragColor = vec4(vec3(v), 1.0);

vec2 uv = fragCoord / iResolution.xy;

vec3 a = vec3(0.5);
vec3 b = vec3(0.5);
vec3 c = vec3(1.0);
vec3 d = vec3(0.0, 0.67, 0.33);

vec3 colour = a + b * cos(6.28318 * (c * uv.x + d));

fragColor = vec4(colour, 1.0);

vec2 uv = fragCoord / iResolution.xy;

vec3 a = vec3(0.5);
vec3 b = vec3(0.5);
vec3 c = vec3(1.0);
vec3 d = vec3(0.0, 0.67, 0.33) + iTime * 0.1;

vec3 colour = a + b * cos(6.28318 * (c * uv.x + d));

fragColor = vec4(colour, 1.0);

vec2 uv = fragCoord / iResolution.xy;
vec2 p = uv * 2.0 - 1.0;
p.x *= iResolution.x / iResolution.y;

float t = length(p);

vec3 a = vec3(0.5);
vec3 b = vec3(0.5);
vec3 c = vec3(2.0);
vec3 phase = vec3(0.0, 0.67, 0.33) + iTime * 0.15;

vec3 colour = a + b * cos(6.28318 * (c * t + phase));

fragColor = vec4(colour, 1.0);
